      if (p.pending.length) return [{ kind: AK.REWARD, x: 0, y: 0, tx: 0, ty: 0, arg: 0 }, { kind: AK.REWARD, x: 0, y: 0, tx: 0, ty: 0, arg: 1 }];
      const A = (kind, x = 0, y = 0, tx = 0, ty = 0, arg = 0) => out.push({ kind, x, y, tx, ty, arg });
